1	/**
2	 * @module useZerarEstoque
3	 *
4	 * Hook para zerar estoque de um produto individual ou de um setor inteiro
5	 * para fins de recontagem física.
6	 *
7	 * Chama as RPCs `zerar_estoque_produto` e `zerar_estoque_setor` — definidas em
8	 * supabase/migrations/20260623120000_zerar_estoque_recontagem.sql.
9	 *
10	 * Contrato de API:
11	 *   - zerarProduto(produtoMasterId, lojaId) → ZerarProdutoResult
12	 *   - zerarSetor(setorNome, lojaId) → ZerarSetorResult
13	 *   - isZerando: boolean
14	 *
15	 * Regras (spec .harness/spec/zerar-estoque-recontagem/spec.md):
16	 *   - R6: loja_id NUNCA hardcoded — vem por parâmetro (chamador usa StoreContext)
17	 *   - R8: idempotente — produto com saldo 0 é no-op (a RPC garante)
18	 *   - R9: acesso restrito a admin — gate na UI (não aqui)
19	 */
20	
21	import { useState } from 'react';
22	import { useQueryClient } from '@tanstack/react-query';
23	import { supabase } from '@/integrations/supabase/client';
24	
25	// ─── Tipos públicos ────────────────────────────────────────────────────────────
26	
27	/** Resultado de `zerarProduto`. Espelha o jsonb retornado pela RPC. */
28	export interface ZerarProdutoResult {
29	  ok: boolean;
30	  noop?: boolean;
31	  saldo_anterior?: number;
32	  saldo_novo?: number;
33	  lotes_zerados?: number;
34	  etiquetas_resetadas?: number;
35	  erro?: string;
36	}
37	
38	/** Resultado de `zerarSetor`. Espelha o jsonb retornado pela RPC. */
39	export interface ZerarSetorResult {
40	  ok: boolean;
41	  setor?: string;
42	  produtos_no_setor?: number;
43	  produtos_zerados?: number;
44	  produtos_noop?: number;
45	  etiquetas_resetadas?: number;
46	  lotes_zerados?: number;
47	  erros?: { produto_master_id: number; erro: string }[];
48	  erro?: string;
49	}
50	
51	// ─── queryKeys a invalidar após zeragem ───────────────────────────────────────
52	//
53	// Evidência grep (src/features/produtos/model/useSetores.ts:76):
54	//   queryKey: ['setores-gestao']
55	//   — única queryKey React Query na feature produtos; Produtos.page.tsx usa
56	//     useState + fetchProdutos() manual, logo não tem queryKey invalidável aqui.
57	//
58	// Invalidar ['setores-gestao'] força re-fetch da contagem de itens por setor
59	// na aba Gerenciar logo após a zeragem.
60	
61	const QUERY_KEYS_TO_INVALIDATE = [['setores-gestao']] as const;
62	
63	// ─── Hook ─────────────────────────────────────────────────────────────────────
64	
65	/**
66	 * Hook de zeragem de estoque para recontagem física.
67	 *
68	 * @example
69	 * ```tsx
70	 * const { zerarProduto, zerarSetor, isZerando } = useZerarEstoque();
71	 * const { selectedStore } = useStoreContext();
72	 *
73	 * const resultado = await zerarProduto(produto.id, selectedStore.id);
74	 * if (!resultado.ok) console.error(resultado.erro);
75	 * ```
76	 */
77	export function useZerarEstoque(): {
78	  zerarProduto: (
79	    produtoMasterId: number,
80	    lojaId: number,
81	  ) => Promise<ZerarProdutoResult>;
82	  zerarSetor: (
83	    setorNome: string,
84	    lojaId: number,
85	  ) => Promise<ZerarSetorResult>;
86	  isZerando: boolean;
87	} {
88	  const queryClient = useQueryClient();
89	  const [isZerando, setIsZerando] = useState(false);
90	
91	  /** Invalida todas as queries React Query afetadas pela zeragem. */
92	  async function invalidarQueries(): Promise<void> {
93	    await Promise.all(
94	      QUERY_KEYS_TO_INVALIDATE.map((key) =>
95	        queryClient.invalidateQueries({ queryKey: key }),
96	      ),
97	    );
98	  }
99	
100	  /**
101	   * Zera o estoque de um produto individual na loja informada.
102	   *
103	   * Guard: lojaId ou produtoMasterId inválidos (null/undefined/0/NaN) retorna
104	   * ok:false sem chamar a RPC.
105	   */
106	  async function zerarProduto(
107	    produtoMasterId: number,
108	    lojaId: number,
109	  ): Promise<ZerarProdutoResult> {
110	    // Guard: entradas inválidas
111	    if (
112	      produtoMasterId == null ||
113	      !Number.isFinite(produtoMasterId) ||
114	      produtoMasterId <= 0
115	    ) {
116	      return { ok: false, erro: 'produtoMasterId inválido.' };
117	    }
118	    if (lojaId == null || !Number.isFinite(lojaId) || lojaId <= 0) {
119	      return { ok: false, erro: 'lojaId inválido.' };
120	    }
121	
122	    setIsZerando(true);
123	    try {
124	      const { data, error } = await supabase.rpc('zerar_estoque_produto', {
125	        p_produto_master_id: produtoMasterId,
126	        p_loja_id: lojaId,
127	      });
128	
129	      if (error) {
130	        return { ok: false, erro: error.message };
131	      }
132	
133	      await invalidarQueries();
134	      return data as ZerarProdutoResult;
135	    } finally {
136	      setIsZerando(false);
137	    }
138	  }
139	
140	  /**
141	   * Zera o estoque de todos os produtos ativos de um setor na loja informada.
142	   *
143	   * Guard: setorNome vazio/nulo ou lojaId inválido retorna ok:false sem chamar
144	   * a RPC.
145	   */
146	  async function zerarSetor(
147	    setorNome: string,
148	    lojaId: number,
149	  ): Promise<ZerarSetorResult> {
150	    // Guard: entradas inválidas
151	    if (!setorNome || setorNome.trim() === '') {
152	      return { ok: false, erro: 'setorNome é obrigatório.' };
153	    }
154	    if (lojaId == null || !Number.isFinite(lojaId) || lojaId <= 0) {
155	      return { ok: false, erro: 'lojaId inválido.' };
156	    }
157	
158	    setIsZerando(true);
159	    try {
160	      const { data, error } = await supabase.rpc('zerar_estoque_setor', {
161	        p_setor_nome: setorNome,
162	        p_loja_id: lojaId,
163	      });
164	
165	      if (error) {
166	        return { ok: false, erro: error.message };
167	      }
168	
169	      await invalidarQueries();
170	      return data as ZerarSetorResult;
171	    } finally {
172	      setIsZerando(false);
173	    }
174	  }
175	
176	  return { zerarProduto, zerarSetor, isZerando };
177	}
