1	import { useEffect, useState } from 'react';
2	import {
3	  Dialog,
4	  DialogContent,
5	  DialogFooter,
6	  DialogHeader,
7	  DialogTitle,
8	} from '@/shared/ui/dialog';
9	import {
10	  Select,
11	  SelectContent,
12	  SelectItem,
13	  SelectTrigger,
14	  SelectValue,
15	} from '@/shared/ui/select';
16	import { Button } from '@/shared/ui/button';
17	import {
18	  AlertDialog,
19	  AlertDialogAction,
20	  AlertDialogCancel,
21	  AlertDialogContent,
22	  AlertDialogDescription,
23	  AlertDialogFooter,
24	  AlertDialogHeader,
25	  AlertDialogTitle,
26	} from '@/shared/ui/alert-dialog';
27	import { useSetores } from '../model/useSetores';
28	import { useZerarEstoque } from '../model/useZerarEstoque';
29	import { useToast } from '@/shared/hooks/use-toast';
30	import { useStoreFilter } from '@/shared/hooks/useStoreData';
31	import { useStore } from '@/shared/contexts/StoreContext';
32	import { usePermissions } from '@/shared/hooks/usePermissions';
33	import { Loader2, Eraser } from 'lucide-react';
34	
35	export interface ProdutoEdit {
36	  id: number;
37	  nome: string;
38	  setor: string;
39	  unidade_medida: string | null;
40	}
41	
42	interface ProdutoSetorUnidadeDialogProps {
43	  open: boolean;
44	  onOpenChange: (v: boolean) => void;
45	  produto: ProdutoEdit | null;
46	  onSaved?: (id: number, setor: string, unidade: string) => void;
47	}
48	
49	const UNIDADES_MEDIDA = [
50	  'unidade',
51	  'kg',
52	  'g',
53	  'l',
54	  'ml',
55	  'm',
56	  'cm',
57	  'caixa',
58	  'fardo',
59	];
60	const UNIDADE_LABELS: Record<string, string> = {
61	  unidade: 'unidade',
62	  kg: 'kg (Quilograma)',
63	  g: 'g (Grama)',
64	  l: 'l (Litro)',
65	  ml: 'ml (Mililitro)',
66	  m: 'm (Metro)',
67	  cm: 'cm (Centímetro)',
68	  caixa: 'caixa',
69	  fardo: 'fardo',
70	};
71	
72	export function ProdutoSetorUnidadeDialog({
73	  open,
74	  onOpenChange,
75	  produto,
76	  onSaved,
77	}: ProdutoSetorUnidadeDialogProps) {
78	  const { setores: setoresCanonicos, atualizarProdutoSetorUnidade } =
79	    useSetores();
80	  const { zerarProduto, isZerando } = useZerarEstoque();
81	  const { storeId } = useStoreFilter();
82	  const { selectedStore } = useStore();
83	  const { isAdmin } = usePermissions();
84	  const { toast } = useToast();
85	
86	  const [setor, setSetor] = useState('');
87	  const [unidade, setUnidade] = useState('unidade');
88	  const [saving, setSaving] = useState(false);
89	  const [confirmZerar, setConfirmZerar] = useState(false);
90	
91	  useEffect(() => {
92	    if (produto) {
93	      const isSetorValido = setoresCanonicos.some((s) => s.nome === produto.setor);
94	      setSetor(isSetorValido ? produto.setor : '');
95	      setUnidade(produto.unidade_medida || 'unidade');
96	    } else {
97	      setSetor('');
98	      setUnidade('unidade');
99	    }
100	  }, [produto, setoresCanonicos]);
101	
102	  const handleSave = async () => {
103	    if (!produto || !setor) return;
104	
105	    setSaving(true);
106	    try {
107	      const result = await atualizarProdutoSetorUnidade(
108	        produto.id,
109	        setor,
110	        unidade,
111	      );
112	      if (result.ok) {
113	        toast({ title: 'Produto atualizado com sucesso!' });
114	        onSaved?.(produto.id, setor, unidade);
115	        onOpenChange(false);
116	      } else {
117	        toast({
118	          title: 'Erro ao atualizar',
119	          description: result.error,
120	          variant: 'destructive',
121	        });
122	      }
123	    } finally {
124	      setSaving(false);
125	    }
126	  };
127	
128	  const handleZerar = async () => {
129	    if (!produto || isZerando) return;
130	    if (!storeId) {
131	      toast({
132	        title: 'Selecione uma loja',
133	        description: 'A zeragem de estoque é feita na loja ativa.',
134	        variant: 'destructive',
135	      });
136	      setConfirmZerar(false);
137	      return;
138	    }
139	    const result = await zerarProduto(produto.id, storeId);
140	    if (result.ok) {
141	      const etiquetas = result.etiquetas_resetadas ?? 0;
142	      toast({
143	        title: result.noop ? 'Estoque já estava zerado' : 'Estoque zerado',
144	        description: `${etiquetas} ${
145	          etiquetas === 1 ? 'etiqueta resetada' : 'etiquetas resetadas'
146	        } para recontagem${
147	          result.noop ? '' : ` · saldo anterior: ${result.saldo_anterior ?? 0}`
148	        }.`,
149	      });
150	      setConfirmZerar(false);
151	      onOpenChange(false);
152	    } else {
153	      toast({
154	        title: 'Erro ao zerar estoque',
155	        description: result.erro,
156	        variant: 'destructive',
157	      });
158	    }
159	  };
160	
161	  return (
162	    <>
163	    <Dialog open={open} onOpenChange={onOpenChange}>
164	      <DialogContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl sm:max-w-[420px]">
165	        <DialogHeader>
166	          <DialogTitle>Editar produto</DialogTitle>
167	          {produto && (
168	            <p className="text-lg font-semibold text-[#2D362E] dark:text-[#E6DCCF] pt-2">
169	              {produto.nome}
170	            </p>
171	          )}
172	        </DialogHeader>
173	        <div className="grid gap-4 py-4">
174	          <div className="grid grid-cols-1 gap-2 sm:grid-cols-4 sm:items-center sm:gap-4">
175	            <label htmlFor="setor" className="sm:text-right text-sm">
176	              Setor
177	            </label>
178	            <div className="col-span-3">
179	              <Select value={setor} onValueChange={setSetor}>
180	                <SelectTrigger
181	                  id="setor"
182	                  data-mia-field="edit_setor"
183	                  data-mia-filter="edit_setor"
184	                  className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus:ring-[#57715B]/30 rounded-xl"
185	                >
186	                  <SelectValue placeholder="Selecione o setor" />
187	                </SelectTrigger>
188	                <SelectContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-xl">
189	                  {setoresCanonicos.map((s) => (
190	                    <SelectItem key={s.nome} value={s.nome}>
191	                      {s.nome}
192	                    </SelectItem>
193	                  ))}
194	                </SelectContent>
195	              </Select>
196	            </div>
197	          </div>
198	          <div className="grid grid-cols-1 gap-2 sm:grid-cols-4 sm:items-center sm:gap-4">
199	            <label htmlFor="unidade" className="sm:text-right text-sm">
200	              Unidade
201	            </label>
202	            <div className="col-span-3">
203	              <Select value={unidade} onValueChange={setUnidade}>
204	                <SelectTrigger
205	                  id="unidade"
206	                  data-mia-field="edit_unidade"
207	                  data-mia-filter="edit_unidade"
208	                  className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus:ring-[#57715B]/30 rounded-xl"
209	                >
210	                  <SelectValue />
211	                </SelectTrigger>
212	                <SelectContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-xl">
213	                  {UNIDADES_MEDIDA.map((u) => (
214	                    <SelectItem key={u} value={u}>
215	                      {UNIDADE_LABELS[u] || u}
216	                    </SelectItem>
217	                  ))}
218	                </SelectContent>
219	              </Select>
220	            </div>
221	          </div>
222	
223	          {isAdmin() && (
224	            <div className="mt-1 rounded-xl border border-amber-500/20 bg-amber-50/60 dark:bg-amber-900/10 p-3">
225	              <div className="flex items-start justify-between gap-3">
226	                <div className="min-w-0">
227	                  <p className="text-xs font-semibold uppercase tracking-wider text-amber-700 dark:text-amber-400">
228	                    Recontagem
229	                  </p>
230	                  <p className="mt-0.5 text-xs text-muted-foreground">
231	                    Zera o estoque deste produto na loja{' '}
232	                    <span className="font-semibold text-[#2D362E] dark:text-[#E6DCCF]">
233	                      {selectedStore?.name ?? 'atual'}
234	                    </span>{' '}
235	                    e reseta as etiquetas para fora do estoque.
236	                  </p>
237	                </div>
238	                <Button
239	                  type="button"
240	                  variant="ghost"
241	                  data-mia-action="zerar_estoque_produto"
242	                  onClick={() => setConfirmZerar(true)}
243	                  disabled={isZerando || !storeId}
244	                  title={
245	                    !storeId
246	                      ? 'Selecione uma loja'
247	                      : 'Zerar estoque para recontagem'
248	                  }
249	                  className="h-9 shrink-0 gap-2 rounded-xl text-amber-700 hover:bg-amber-500/10 hover:text-amber-800"
250	                >
251	                  <Eraser className="h-4 w-4" />
252	                  Zerar
253	                </Button>
254	              </div>
255	            </div>
256	          )}
257	        </div>
258	        <DialogFooter>
259	          <Button variant="ghost" data-mia-action="cancelar_edicao" onClick={() => onOpenChange(false)}>
260	            Cancelar
261	          </Button>
262	          <Button
263	            data-mia-action="salvar_setor_unidade"
264	            onClick={handleSave}
265	            disabled={!setor || saving}
266	            className="bg-[#57715B] hover:bg-[#465b49] text-white rounded-xl"
267	          >
268	            {saving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
269	            Salvar
270	          </Button>
271	        </DialogFooter>
272	      </DialogContent>
273	    </Dialog>
274	
275	    {/* AlertDialog de confirmação de zeragem de estoque do produto */}
276	    <AlertDialog
277	      open={confirmZerar}
278	      onOpenChange={(isOpen) => !isOpen && setConfirmZerar(false)}
279	    >
280	      <AlertDialogContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
281	        <AlertDialogHeader>
282	          <AlertDialogTitle className="flex items-center gap-2 text-[#2D362E] dark:text-[#E6DCCF]">
283	            <Eraser className="h-5 w-5 text-amber-600" />
284	            Zerar estoque do produto?
285	          </AlertDialogTitle>
286	          <AlertDialogDescription className="space-y-2">
287	            <span className="block">
288	              Isto vai{' '}
289	              <span className="font-bold text-amber-700">zerar o saldo</span> de{' '}
290	              <span className="font-bold text-[#2D362E] dark:text-[#E6DCCF]">
291	                {produto?.nome}
292	              </span>{' '}
293	              na loja{' '}
294	              <span className="font-bold text-[#2D362E] dark:text-[#E6DCCF]">
295	                {selectedStore?.name ?? 'atual'}
296	              </span>{' '}
297	              e resetar as caixas para “fora do estoque” (recontagem).
298	            </span>
299	            <span className="block">
300	              Outras lojas não são afetadas — a recontagem reconstrói o saldo ao
301	              rebipar.
302	            </span>
303	          </AlertDialogDescription>
304	        </AlertDialogHeader>
305	        <AlertDialogFooter>
306	          <AlertDialogCancel asChild>
307	            <Button variant="ghost" className="rounded-xl">
308	              Cancelar
309	            </Button>
310	          </AlertDialogCancel>
311	          <AlertDialogAction
312	            className="bg-amber-600 hover:bg-amber-700 text-white rounded-xl"
313	            onClick={handleZerar}
314	            disabled={isZerando}
315	          >
316	            {isZerando && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
317	            Zerar estoque
318	          </AlertDialogAction>
319	        </AlertDialogFooter>
320	      </AlertDialogContent>
321	    </AlertDialog>
322	    </>
323	  );
324	}
